// Synthetic cases only: example.com addresses, made-up text, no real people.
const stamp = Date.now().toString(36);
const good = { name: 'Synthetic Buyer One', email: 'synthetic.buyer1.' + stamp + '@example.com', phone: '555-0100', source: 'pg-test', message: 'Synthetic inquiry: interested in a three-bedroom home. Test data only.' };
const long = { name: 'Synthetic Buyer Three', email: 'synthetic.long.' + stamp + '@example.com', phone: '555-0102', source: 'pg-test', message: 'x'.repeat(2001) };
const err = { name: 'Synthetic Buyer Four', email: 'synthetic.err.' + stamp + '@example.com', phone: '555-0103', source: 'pg-force-error', message: 'Synthetic forced error. Test data only.' };
const cases = [
  { case: 'T5', description: 'oversize message is rejected', auth: true, payload: long, expect_code: 400, expect_status: 'rejected' },
  { case: 'T7', description: 'forced error is caught by the error workflow', auth: true, payload: err, expect_code: 500, expect_status: '' },
  { case: 'T8', description: 'request without the key is refused', auth: false, payload: good, expect_code: 403, expect_status: '' }
];
return cases.map(function (c) { return { json: c }; });

const all = $('Synthetic cases').all().map(function (i) { return i.json; });
const withKey = $('Send with key').all().map(function (i) { return i.json; });
const noKey = $('Send without key').all().map(function (i) { return i.json; });
let a = 0;
let b = 0;
return all.map(function (c) {
  const res = c.auth ? withKey[a++] : noKey[b++];
  const code = res ? res.statusCode : null;
  let body = res ? res.body : undefined;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
  const status = body && body.status ? body.status : '';
  const pass = code === c.expect_code && (!c.expect_status || status === c.expect_status);
  return { json: { case: c.case, description: c.description, expected: c.expect_code + (c.expect_status ? ' ' + c.expect_status : ''), got: String(code) + (status ? ' ' + status : ''), result: pass ? 'PASS' : 'FAIL' } };
});
